IF OBJECT_ID('CustomerAddresses','U') IS NULL
CREATE TABLE CustomerAddresses (id INT IDENTITY PRIMARY KEY, user_id NVARCHAR(100) NOT NULL, address_text NVARCHAR(500) NOT NULL, is_default BIT NOT NULL DEFAULT 0, is_active BIT NOT NULL DEFAULT 1, created_at DATETIME2 NOT NULL DEFAULT GETDATE(), updated_at DATETIME2 NOT NULL DEFAULT GETDATE());
IF OBJECT_ID('CustomerPreferences','U') IS NULL
CREATE TABLE CustomerPreferences (user_id NVARCHAR(100) PRIMARY KEY, marketing_email BIT NOT NULL DEFAULT 0, updated_at DATETIME2 NOT NULL DEFAULT GETDATE());
